package com.example.jalalidaily;
import android.content.*;import org.json.*;import java.time.*;import java.util.*;
public final class DayBundles {
 private static final String PREF="bundles";
 static synchronized void migrate(Context c){SharedPreferences p=c.getSharedPreferences(PREF,0);if(p.getBoolean("_legacy_imported",false))return;JSONArray old=Store.all(c);SharedPreferences.Editor e=p.edit();java.util.HashMap<String,JSONArray> grouped=new java.util.HashMap<>();for(int i=0;i<old.length();i++){JSONObject o=old.optJSONObject(i);if(o==null)continue;String date=o.optString("date");if(date.isEmpty())continue;JSONArray a=grouped.containsKey(date)?grouped.get(date):raw(c,date);try{String body=o.optString("body");String t=o.optString("title")+(body.isEmpty()?"":" — "+body);a.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("emoji",o.optString("sticker","📝")).put("text",t).put("done",o.optBoolean("done")));grouped.put(date,a);}catch(Exception ignored){}}for(java.util.Map.Entry<String,JSONArray> item:grouped.entrySet())e.putString(item.getKey(),item.getValue().toString());e.putBoolean("_legacy_imported",true).commit();}
 static JSONArray raw(Context c,String date){try{return new JSONArray(c.getSharedPreferences(PREF,0).getString(date,"[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized JSONArray get(Context c,String date){migrate(c);return raw(c,date);}
 static synchronized void save(Context c,String date,JSONArray tasks){c.getSharedPreferences(PREF,0).edit().putString(date,tasks.toString()).commit();}
 static synchronized void add(Context c,String date,String emoji,String text){JSONArray a=get(c,date);try{a.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("emoji",emoji).put("text",text).put("done",false));save(c,date,a);}catch(Exception ignored){}}
 static synchronized void done(Context c,String date,int index,boolean value){JSONArray a=get(c,date);JSONObject o=a.optJSONObject(index);if(o!=null){try{o.put("done",value);}catch(Exception ignored){}save(c,date,a);}}
 static synchronized void remove(Context c,String date,int index){JSONArray a=get(c,date),b=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)b.put(a.opt(i));save(c,date,b);}
 static synchronized void toggleById(Context c,String id){migrate(c);SharedPreferences p=c.getSharedPreferences(PREF,0);for(Map.Entry<String,?> entry:p.getAll().entrySet()){String key=entry.getKey();if(!key.matches("\\d{4}-\\d{2}-\\d{2}"))continue;JSONArray a=raw(c,key);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&id.equals(o.optString("id"))){try{o.put("done",!o.optBoolean("done"));save(c,key,a);}catch(Exception ignored){}return;}}}}
 static LocalDate dateFromKey(String k){try{String[] p=k.split("-");return Jalali.toGregorian(Integer.parseInt(p[0]),Integer.parseInt(p[1]),Integer.parseInt(p[2]));}catch(Exception e){return null;}}
 static String keyFromDate(LocalDate d){return Jalali.key(Jalali.fromGregorian(d));}
 static LocalDate target(LocalDate today){int w=(today.getDayOfWeek().getValue()+1)%7;return w<=4?today:today.plusDays(w==5?2:1);}
 static synchronized void rolloverUnfinishedTasks(Context c){migrate(c);LocalDate today=LocalDate.now(ZoneId.of("Asia/Tehran"));LocalDate dest=target(today);String destKey=keyFromDate(dest);SharedPreferences p=c.getSharedPreferences(PREF,0);Map<String,?> all=p.getAll();JSONArray destination=raw(c,destKey);Set<String> ids=new HashSet<>();for(int i=0;i<destination.length();i++){JSONObject o=destination.optJSONObject(i);if(o!=null)ids.add(o.optString("id"));}
 SharedPreferences.Editor edit=p.edit();boolean changed=false;for(String k:all.keySet()){if(!k.matches("\\d{4}-\\d{2}-\\d{2}")||k.equals(destKey))continue;LocalDate source=dateFromKey(k);if(source==null||!source.isBefore(today))continue;JSONArray existing=raw(c,k),keep=new JSONArray();boolean moved=false;for(int i=0;i<existing.length();i++){JSONObject o=existing.optJSONObject(i);if(o==null)continue;if(o.optBoolean("done")){keep.put(o);continue;}try{String id=o.optString("id");if(id.isEmpty()){id=UUID.randomUUID().toString();o.put("id",id);}if(ids.add(id))destination.put(o);moved=true;}catch(Exception e){keep.put(o);}}if(moved){edit.putString(k,keep.toString());changed=true;}}
 if(changed){edit.putString(destKey,destination.toString());edit.commit();}}
 static synchronized void ensureIds(Context c,String date){JSONArray a=get(c,date);boolean changed=false;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optString("id").isEmpty()){try{o.put("id",UUID.randomUUID().toString());changed=true;}catch(Exception ignored){}}}if(changed)save(c,date,a);}
}
